INSERT INTO collections (slug,display_name,owner_id,data,status,created_at,updated_at) VALUES ('the-menagerie','The Menagerie',NULL,'{"slug":"the-menagerie","id":"the-menagerie","displayName":"The Menagerie","creator":"Goodpart","synopsis":"The Menagerie is an almanac for a collection of homebrew characters for Blood on the Clocktower designed to be adapted to scripts containing standard Clocktower characters. Think of it as an \"expansion pack\"!\n\nPlease contact me on Discord (@Goodpart) if something isn''t working, or if you have any feedback. Although tested for balance, these characters have not been run with every given permutation of scripts, and so your comments are absolutely welcome - especially around jinxes, if there are any interactions that feel particularly fun/awful.\n\nThanks to all the players who were patient with me while testing, thanks to friends who talked through concepts and got these characters working in the first place, and of course, thanks to The Pandemonium Institute for making such a wonderful game.","logo":"https://menagerie.towerrangers.net/images/unnamed.png","match":["themenagerie"],"include":["astrologer","banker-the-menagerie","cartographer-the-menagerie","chameleon-the-menagerie","cleric-the-menagerie","conspiracist-the-menagerie","daredevil-the-menagerie","dentist-the-menagerie","disciple-the-menagerie","evangelist","gatekeeper-the-menagerie","guardian-the-menagerie","houndmaster","lost-lover","martyr-the-menagerie","mime-the-menagerie","mechanical-man","medicine-man","mentalist-the-menagerie","mortician","old-sheriff","prophet-the-menagerie","ronin-the-menagerie","seer-the-menagerie","shinkan","sleeper-the-menagerie","smith-the-menagerie","swindler-the-menagerie","thaumaturge-the-menagerie","wire-tapper","barfly","blasphemer","colossus","eccentric","egotist","fixer","missionary","oaf","record-keeper","snoop-the-menagerie","stowaway-the-menagerie","thrall","yang","arbiter-the-menagerie","blackmailer","chatterpox","counterfeiter","crook-the-menagerie","doppelganger-the-menagerie","efreet","embalmer-the-menagerie","firebug","gerrymanderer","lady-lace","muckraker","necromancer-the-menagerie","saboteur-the-menagerie","wispr","abomination","baku-the-menagerie","chronos","ein","hypnox","patient-zero","polterghast","seiren","shogun-the-menagerie","umbra","yin","yin-yang","zwei","mad-scientist","tactician-the-menagerie","taxidermist-the-menagerie","peanut-gallery","mercy-society","pyro","parasitoid","present-peeker","party-pooper-the-menagerie","la-befana","krampus","santa-claus"],"exclude":[],"curata":false}','published',datetime('now'),datetime('now'));